                R(ref s, "You're still here, <E049><E003 8><E025 2>are you, <E049><E003 8>Dr Mikotoba?", "Vous êtes toujours parmi nous, <E049><E003 8><E025 2>à ce que je vois, <E049><E003 8>Dr Mikotoba ?");
